//! Event types preserve exact UTF-16 units through native storage and matching.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->Value{p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div id=box>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://event-units.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
#[test]
fn event_type_units_native_constructors_preserve_code_units_and_detail_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var type='a\ud800\u0000\udfff\ud83d\udc31',detail={actual:true};for(var C of [Event,CustomEvent,UIEvent,MouseEvent,KeyboardEvent,FocusEvent,WheelEvent,AnimationEvent,ProgressEvent,ErrorEvent,SubmitEvent]){var e=new C(type,{});if(e.type!==type||e.type.length!==6||e.type.charCodeAt(1)!==0xd800||e.type.charCodeAt(3)!==0xdfff||e.isTrusted)throw 'exact constructor type';}var custom=new CustomEvent(type,{detail:detail});if(custom.detail!==detail)throw 'detail native identity';var conversions=0,e=new Event({toString:function(){conversions++;return type;}});if(conversions!==1||e.type!==type)throw 'converted raw type';
"#);assert!(p.state.created_events.iter().all(|e|!e.dispatching));}
#[test]
fn event_type_units_legacy_initializers_preserve_native_state_and_conversion(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var type='\ud800X\udfff',detail={held:true};for(var name of ['Event','CustomEvent','UIEvent','MouseEvent']){var e=document.createEvent(name);if(name==='CustomEvent')e.initCustomEvent(type,true,true,detail);else if(name==='UIEvent')e.initUIEvent(type,true,true,window,7);else if(name==='MouseEvent')e.initMouseEvent(type,true,true,window,7);else e.initEvent(type,true,true);if(e.type!==type||!e.bubbles||!e.cancelable||e.isTrusted)throw 'exact initializer type';if(name==='CustomEvent'&&e.detail!==detail)throw 'legacy detail identity';if((name==='UIEvent'||name==='MouseEvent')&&(e.view!==window||e.detail!==7))throw 'legacy native UI data';e.preventDefault();e.initEvent('\udfff\u0000',false,false);if(e.type!=='\udfff\u0000'||e.defaultPrevented||e.bubbles||e.cancelable)throw 'exact reinitialize reset';}
"#);}
#[test]
fn event_type_units_listener_identity_removal_nested_once_and_abort_are_exact(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var target=new EventTarget(),raw='\ud800',other='\udfff',replacement='\ufffd',pair='\ud83d\udc31',log='',controller=new AbortController();function callback(e){log+=e.type===raw?'R':e.type===other?'L':e.type===replacement?'P':e.type===pair?'S':'?';}for(var type of [raw,other,replacement,pair])target.addEventListener(type,callback);target.addEventListener(raw,callback,{once:true});for(var type of [raw,other,replacement,pair])target.dispatchEvent(new Event(type));if(log!=='RLPS')throw 'exact matching or duplicate';target.removeEventListener(raw,callback);target.dispatchEvent(new Event(raw));target.dispatchEvent(new Event(other));if(log!=='RLPSL')throw 'exact removal';target.addEventListener(raw,function(){log+='A';controller.abort();target.dispatchEvent(new Event(other));},{once:true});target.addEventListener(raw,function(){throw 'aborted raw listener';},{signal:controller.signal});target.dispatchEvent(new Event(raw));target.dispatchEvent(new Event(raw));if(log!=='RLPSLAL')throw 'nested once abort exact identity';
"#);}
#[test]
fn event_type_units_actual_main_inert_and_child_paths_keep_exact_types_and_authority(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var type='load\ud800',calls=0,frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow,target=child.document.body,saved=child.EventTarget.prototype.dispatchEvent,ChildEvent=child.Event,held=new ChildEvent(type,{bubbles:true});var inert=new Document(),root=inert.createElement('Root');inert.appendChild(root);for(var node of [document.body,root,target]){node.addEventListener(type,function(e){if(e.type!==type||e.target!==this)throw 'actual exact type target';calls++;});if(!node.dispatchEvent(new Event(type,{bubbles:true})))throw 'dispatch result';}if(calls!==3)throw 'native targets';var captured=0;child.EventTarget.prototype.addEventListener.call(child,type,function(e){captured++;if(e.composedPath()[3]!==child)throw 'own child Window';},true);saved.call(target,held);if(calls!==4||captured!==1)throw 'load suffix still reaches Window';document.body;
"#);p.set_location(&crate::navigation::address("https://other.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();let before=p.state.retained;let error=p.runtime.execute("saved.call(target,held)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");assert_eq!(p.state.retained,before);assert!(p.state.synthetic_dispatches.is_empty());p.set_location(&crate::navigation::address("https://event-units.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"saved.call(target,held);if(calls!==5||captured!==2)throw 'exact type authority recovery';");}
#[test]
fn event_type_units_refusal_preserves_event_listener_dispatch_state_and_recovers(){
 for operation in 0..4{for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var type='\ud800\u0000\udfff',target=new EventTarget(),event=new Event('old',{cancelable:true}),rawEvent=new Event(type),calls=0;function callback(){calls++;}function second(){calls++;}target.addEventListener(type,callback);event.preventDefault();"#);let before=(p.state.retained,p.state.listeners.len(),p.state.created_events.len());let limit=p.state.retained_limit;p.begin_job();match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())}let source=match operation{0=>"new Event(type)",1=>"event.initEvent(type)",2=>"target.dispatchEvent(rawEvent)",_=>"target.addEventListener(type,second)"};assert!(p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((p.state.retained,p.state.listeners.len(),p.state.created_events.len()),before);assert!(p.state.synthetic_dispatches.is_empty());assert!(p.state.created_events.iter().all(|e|!e.dispatching));p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"if(calls||event.type!=='old'||!event.defaultPrevented)throw 'refusal prefix';event.initEvent(type);if(event.type!==type||event.defaultPrevented)throw 'initializer recovery';target.dispatchEvent(rawEvent);if(calls!==1)throw 'dispatch recovery';");}}
}

#[test]
fn event_type_units_owned_representation_admission_and_initializer_refund_are_exact(){
 let(mut d,mut f,mut p)=fixture();let base=p.state.retained;let limit=p.state.retained_limit;let slot=std::mem::size_of::<script_created_events::CreatedEvent>();let args=[Value::StringUnits(vec![0xd800])];
 p.state.retained_limit=base+slot+4;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.construct_base_event(WINDOW,&args,None).is_err());assert_eq!(p.state.retained,base);assert!(p.state.created_events.is_empty());
 p.state.retained_limit=base+slot+5;p.begin_job();let Value::Host(handle)=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.construct_base_event(WINDOW,&args,None).unwrap()else{panic!("genuine native Event")};assert_eq!(p.state.created_events.capacity(),1);assert_eq!(p.state.created_events[0].name.capacity(),5);assert_eq!(p.state.retained,base+slot+5);
 let value=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.created_event_get(handle,"type").unwrap().unwrap();assert!(matches!(value,Value::StringUnits(units)if units==[0xd800]));
 p.state.retained_limit=limit;p.begin_job();Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.created_event_call(handle,"initEvent",&[Value::String("x".into())]).unwrap().unwrap();assert_eq!(p.state.retained,base+slot+1);
 p.state.retained_limit=p.state.retained+3;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.created_event_call(handle,"initEvent",&args).unwrap().is_err());assert_eq!(p.state.retained,base+slot+1);assert_eq!(p.state.created_events[0].name,"x");
 p.state.retained_limit=limit;p.begin_job();Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.created_event_call(handle,"initEvent",&args).unwrap().unwrap();assert_eq!(p.state.retained,base+slot+5);assert_eq!(p.state.created_events[0].name.raw_units(),Some(&[0xd800][..]));Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.rollback_base_event(handle).unwrap();assert_eq!(p.state.retained,base);assert!(p.state.created_events.is_empty());
}
